<?php
declare(strict_types=1);
$base=getenv('SHIPPING_URL')?:'http://shipping-api:8000';$cookie=tempnam(sys_get_temp_dir(),'shipping-session-');
function web(string $path,?string $body=null,array $headers=[]):array{global $base,$cookie;$c=curl_init(str_starts_with($path,'http')?$path:$base.$path);curl_setopt_array($c,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>10,CURLOPT_FOLLOWLOCATION=>true,CURLOPT_COOKIEFILE=>$cookie,CURLOPT_COOKIEJAR=>$cookie,CURLOPT_HTTPHEADER=>$headers]);if($body!==null)curl_setopt_array($c,[CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>$body]);$raw=curl_exec($c);$code=(int)curl_getinfo($c,CURLINFO_RESPONSE_CODE);curl_close($c);return [$code,$raw];}
function check(bool $ok,string $name):void{if(!$ok)throw new RuntimeException($name);echo "PASS $name\n";}
function token(string $html):string{if(!preg_match('/name="_token" value="([^"]+)"/',$html,$m))throw new RuntimeException('CSRF token missing');return html_entity_decode($m[1],ENT_QUOTES);}
try{[$code,$html]=web('/');check($code===200&&str_contains($html,'Username')&&str_contains($html,'Password'),'Blade sign-in form served by production runtime');$token=token($html);[$code,$html]=web('/signin',http_build_query(['_token'=>$token,'username'=>'employee','password'=>'employee-smoke']));check($code===200&&str_contains($html,'Sign out')&&!str_contains($html,'Run controls')&&!str_contains($html,'Load audit'),'employee session receives sample ledger without operator controls');check(!str_contains($html,'employee-smoke'),'browser response never contains stored password');$token=token($html);
    if(!str_contains($html,'wire:snapshot'))fwrite(STDERR,strip_tags(preg_replace('/<script\b[^>]*>.*?<\/script>/s','',$html))."\n");check((bool)preg_match('/wire:snapshot="([^"]+)"/',$html,$snapshot),'Livewire component renders a signed snapshot');check((bool)preg_match('/data-update-uri="([^"]+)"/',$html,$route),'Livewire update route is present');$body=['_token'=>$token,'components'=>[['snapshot'=>html_entity_decode($snapshot[1],ENT_QUOTES),'updates'=>(object)[],'calls'=>[['path'=>'','method'=>'control','params'=>['hold']]]]]];[$code,$response]=web(html_entity_decode($route[1],ENT_QUOTES),json_encode($body),['Content-Type: application/json','X-Livewire: true','X-CSRF-TOKEN: '.$token]);check($code===200&&str_contains($response,'This identity cannot perform the requested action'),'forged employee Livewire operator action denied on server (HTTP '.$code.', '.(json_decode(is_string($response)?$response:'{}',true)['message']??'no message').')');
    [$code,$html]=web('/signout',http_build_query(['_token'=>$token]));check($code===200&&str_contains($html,'Sign in')&&!str_contains($html,'Sign out'),'sign out invalidates private server session');
}finally{unlink($cookie);}
